           setLoading({ isLoading: false, message: '' });
           return;
        }
      }

      let mimeType = blob.type;
      if (!mimeType || mimeType === 'application/octet-stream') {
         const ext = urlInput.split('.').pop()?.toLowerCase();
         if (['jpg', 'jpeg'].includes(ext || '')) mimeType = 'image/jpeg';
         else if (['png'].includes(ext || '')) mimeType = 'image/png';
         else if (['mov'].includes(ext || '')) mimeType = 'video/quicktime';
         else if (['mp3', 'wav', 'ogg'].includes(ext || '')) mimeType = 'audio/mpeg';
         else mimeType = 'video/mp4';
         blob = blob.slice(0, blob.size, mimeType);
      }

      if (mimeType.includes('text/html')) {
          setFileData({
              file: null,
              previewUrl: '',
              type: 'url',
              base64: '',
              mimeType: '',
              url: urlInput
           });
           setError("Link này là trang web. Đã chuyển sang chế độ đọc Link.");
           setLoading({ isLoading: false, message: '' });
           return;
      }

      if (blob.size > 500 * 1024 * 1024) {
        throw new Error("File từ link quá lớn (>500MB). Vui lòng dùng file nhỏ hơn.");
      }

      const type = mimeType.startsWith('image') ? 'image' : 
                   mimeType.startsWith('audio') ? 'audio' : 'video';

      if (type === 'image') {
        if (selectedMode !== AnalysisMode.CONTENT_AUDIT && selectedMode !== AnalysisMode.SCRIPT_GENERATION) {
           setSelectedMode(AnalysisMode.THUMBNAIL_AUDIT);
        }
      } else if (type === 'audio') {
         setSelectedMode(AnalysisMode.CONTENT_AUDIT);
      } else if (selectedMode === AnalysisMode.THUMBNAIL_AUDIT) {
        setSelectedMode(AnalysisMode.SCRIPT_EXTRACT);
      }

      const { inlineData } = await fileToGenerativePart(blob);
      setFileData({
        file: null,
        previewUrl: URL.createObjectURL(blob),
        type,
        base64: inlineData.data,
        mimeType: mimeType
      });

    } catch (err: any) {
      console.error(err);
      setError("Lỗi tải link: " + (err.message || "Vui lòng kiểm tra lại đường dẫn."));
    } finally {
      setLoading({ isLoading: false, message: '' });
    }
  };

  const handleAnalyze = async () => {
    if (!apiKey) {
      setError("Không tìm thấy API Key (process.env.API_KEY).");
      return;
    }

    if (!fileData && selectedMode !== AnalysisMode.CONTENT_AUDIT && selectedMode !== AnalysisMode.SCRIPT_GENERATION) return;

