import React from 'react';
import { FileVideo, FileImage, UploadCloud, Loader2, Sparkles, FileText, ScanEye, RefreshCw, Copy, Check, Plus, Newspaper, Clapperboard, FileAudio } from 'lucide-react';
import { AnalysisMode } from '../types';

// Fix: Added title prop to the Button component to support native HTML title attribute and fix type error
export const Button = ({ 
  children, 
  onClick, 
  variant = 'primary', 
  className = '', 
  disabled = false,
  icon: Icon,
  title
}: { 
  children?: React.ReactNode; 
  onClick?: () => void; 
  variant?: 'primary' | 'secondary' | 'ghost' | 'outline'; 
  className?: string;
  disabled?: boolean;
  icon?: React.ElementType;
  title?: string;
}) => {
  const baseStyle = "inline-flex items-center justify-center gap-2 px-4 py-2 rounded-lg font-medium transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-[#0f172a]";

  const variants = {
    primary: "bg-gradient-to-r from-indigo-500 to-purple-600 hover:from-indigo-600 hover:to-purple-700 text-white shadow-lg shadow-indigo-500/25 border border-transparent",
    secondary: "bg-slate-700 hover:bg-slate-600 text-white border border-slate-600",
    ghost: "bg-transparent hover:bg-slate-800 text-slate-300 hover:text-white",
    outline: "bg-transparent border border-slate-600 text-slate-300 hover:border-slate-400 hover:text-white"
  };

  return (
    <button 
      onClick={onClick} 
      disabled={disabled}
      title={title}
      className={`${baseStyle} ${variants[variant]} ${disabled ? 'opacity-50 cursor-not-allowed' : ''} ${className}`}
    >
      {Icon && <Icon className="w-4 h-4" />}
      {children}
    </button>
  );
};

export const FeatureCard = ({ 
  mode, 
  active, 
  onClick, 
  disabled 
}: { 
  mode: AnalysisMode; 
  active: boolean; 
  onClick: () => void; 
  disabled: boolean 
}) => {
  let icon, title, desc;

  switch (mode) {
    case AnalysisMode.SCRIPT_EXTRACT:
      icon = FileText;
      title = "Trích Xuất Script";
      desc = "Chép lại lời thoại chi tiết từ video.";
      break;
    case AnalysisMode.DEEP_ANALYSIS:
      icon = ScanEye;
      title = "Phân Tích Sâu";
      desc = "Lời thoại, hình ảnh & nội dung từng đoạn.";
      break;
    case AnalysisMode.THUMBNAIL_AUDIT:
      icon = FileImage;
      title = "Audit Thumbnail";
      desc = "Đánh giá màu sắc, text & độ thu hút.";
      break;
    case AnalysisMode.REMAKE_SCRIPT:
      icon = RefreshCw;
      title = "Remake Kịch Bản";
      desc = "Viết lại script hài hước cho kênh của bạn.";
      break;
    case AnalysisMode.CONTENT_AUDIT:
      icon = Newspaper;
      title = "Remake Bài Viết";
      desc = "Từ Text/Link/Ảnh/Audio -> AI viết bài mới.";
      break;
    case AnalysisMode.SCRIPT_GENERATION:
      icon = Clapperboard;
      title = "Tạo Script TikTok";
      desc = "Từ ý tưởng -> Kịch bản viral hoàn chỉnh.";
      break;
    case AnalysisMode.THUMBNAIL_GENERATE: // Just a placeholder, usually handled inside Audit
      icon = Sparkles;
      title = "Tạo Thumbnail";
      desc = "AI Remake.";
      break;
    case AnalysisMode.CONTENT_REMAKE:
      icon = RefreshCw;
      title = "Xào Lại Content";
      desc = "Viết lại bài post mới.";
      break;
  }

  const IconComponent = icon as React.ElementType;

  return (
    <button
      onClick={onClick}
      disabled={disabled}
      className={`
        relative overflow-hidden group p-4 rounded-xl border text-left transition-all duration-300 w-full h-full
        ${active 
          ? 'bg-indigo-600/10 border-indigo-500 shadow-[0_0_20px_rgba(99,102,241,0.3)]' 
          : 'bg-slate-800/50 border-slate-700 hover:border-slate-500 hover:bg-slate-800'}
        ${disabled ? 'opacity-40 cursor-not-allowed grayscale' : ''}
      `}
    >
      <div className={`p-3 rounded-lg inline-block mb-3 ${active ? 'bg-indigo-500 text-white' : 'bg-slate-700 text-slate-400 group-hover:text-white'}`}>
        <IconComponent className="w-6 h-6" />
      </div>
      <h3 className={`font-semibold mb-1 ${active ? 'text-white' : 'text-slate-200'}`}>{title}</h3>
      <p className="text-xs text-slate-400 leading-relaxed">{desc}</p>

      {active && (
        <div className="absolute top-2 right-2 w-2 h-2 rounded-full bg-indigo-400 shadow-[0_0_10px_#818cf8]"></div>
      )}
    </button>
  );
};

export const FileDropzone = ({ 
  onFileSelect, 
  currentFile, 
  variant = 'normal',
  label = "Kéo thả Video, Audio hoặc Thumbnail"
}: { 
  onFileSelect: (file: File) => void;
  currentFile: File | null;
  variant?: 'normal' | 'mini';
  label?: string;
}) => {
  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      onFileSelect(e.dataTransfer.files[0]);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      onFileSelect(e.target.files[0]);
    }
  };

  if (variant === 'mini') {
    return (
      <div 
        onDragOver={(e) => e.preventDefault()}
        onDrop={handleDrop}
        className={`
          relative border border-dashed rounded-lg p-4 text-center transition-all duration-300 group
          ${currentFile ? 'border-green-500 bg-green-500/10' : 'border-slate-600 hover:border-slate-500 hover:bg-slate-800'}
        `}
      >
        <input 
          type="file" 
          accept="image/*" 
          onChange={handleChange} 
          className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
        />
        <div className="flex items-center gap-3">
          <div className={`w-10 h-10 rounded-lg flex items-center justify-center shrink-0 ${currentFile ? 'bg-green-500/20 text-green-400' : 'bg-slate-700 text-slate-400'}`}>
            {currentFile ? <Check className="w-5 h-5" /> : <Plus className="w-5 h-5" />}
          </div>
          <div className="text-left overflow-hidden">
             <p className={`text-sm font-medium truncate ${currentFile ? 'text-green-300' : 'text-slate-300'}`}>
               {currentFile ? currentFile.name : label}
             </p>
             <p className="text-xs text-slate-500">{currentFile ? 'Đã sẵn sàng' : 'PNG, JPG (Trong suốt càng tốt)'}</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div 
      onDragOver={(e) => e.preventDefault()}
      onDrop={handleDrop}
      className={`
        relative border-2 border-dashed rounded-2xl p-8 text-center transition-all duration-300
        ${currentFile ? 'border-indigo-500 bg-indigo-500/5' : 'border-slate-600 hover:border-slate-500 hover:bg-slate-800/50'}
      `}
    >
      <input 
        type="file" 
        accept="video/*,image/*,audio/*" 
        onChange={handleChange} 
        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
      />

      <div className="flex flex-col items-center justify-center gap-3">
        {currentFile ? (
          <>
            <div className="w-16 h-16 rounded-full bg-indigo-500/20 flex items-center justify-center text-indigo-400 mb-2">
              {currentFile.type.startsWith('video') ? <FileVideo className="w-8 h-8" /> : 
               currentFile.type.startsWith('audio') ? <FileAudio className="w-8 h-8" /> : 
               <FileImage className="w-8 h-8" />}
            </div>
            <div>
              <p className="text-white font-medium truncate max-w-xs">{currentFile.name}</p>
              <p className="text-xs text-slate-400 mt-1">{(currentFile.size / (1024 * 1024)).toFixed(2)} MB</p>
            </div>
            <p className="text-xs text-indigo-300 bg-indigo-500/10 px-3 py-1 rounded-full mt-2">
              Nhấp hoặc kéo thả để thay đổi
            </p>
          </>
        ) : (
          <>
            <div className="w-16 h-16 rounded-full bg-slate-700/50 flex items-center justify-center text-slate-400 mb-2 group-hover:scale-110 transition-transform">
              <UploadCloud className="w-8 h-8" />
            </div>
            <h3 className="text-lg font-medium text-slate-200">{label}</h3>
            <p className="text-sm text-slate-400">Hỗ trợ Video, Audio (MP3/WAV), Ảnh. (Tối đa 500MB)</p>
            <Button variant="secondary" className="mt-4 pointer-events-none">Chọn File</Button>
          </>
        )}
      </div>
    </div>
  );
};

