// Helper to convert file/blob to base64 for inlineData
export const fileToGenerativePart = async (file: Blob): Promise<{ inlineData: { data: string; mimeType: string } }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      // Remove the Data-URL prefix (e.g. "data:video/mp4;base64,")
      const base64Data = base64String.split(',')[1];
      resolve({
        inlineData: {
          data: base64Data,
          mimeType: file.type || 'application/octet-stream',
        },
      });
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

const getToneInstruction = (tone?: ContentTone): string => {
  switch (tone) {
    case 'funny': 
      return `
      - PHONG CÁCH: Hài hước, lầy lội, "bựa", giọng văn đàn ông, phóng khoáng.
      - NGÔI XƯNG: "Tui - Mấy ông", "Ông - Tui", "Anh em - Tui", hoặc "Ad - Anh em" (kiểu vui vẻ). KHÔNG DÙNG "mấy bà".
      - ĐẶC ĐIỂM: Dùng từ lóng (slang) nam tính, dứt khoát. Cấu trúc câu ngắt nhịp bất ngờ, gây cười kiểu tưng tửng.`;

    case 'professional': 
      return `
      - PHONG CÁCH: Chuyên gia, nghiêm túc, nam tính, đáng tin cậy.
      - NGÔI XƯNG: "Tôi - Các bạn", "Chúng tôi - Quý vị", hoặc "Mình - Bạn" (lịch sự).
      - ĐẶC ĐIỂM: Dùng từ ngữ chính xác, thuật ngữ chuyên ngành (nếu cần), dẫn chứng số liệu. Không dùng slang, không cợt nhả. Cấu trúc câu gãy gọn, logic.`;

    case 'friendly': 
      return `
      - PHONG CÁCH: Thân thiện, gần gũi, như hai người bạn trai nói chuyện với nhau (Bro-to-bro).
      - NGÔI XƯNG: "Mình - Anh em", "Mình - Mọi người", "Tớ - Cậu" (nếu trẻ), hoặc "Tôi - Anh em".
      - ĐẶC ĐIỂM: Giọng văn ấm áp, chia sẻ chân thành, thẳng thắn. Khuyến khích sự tương tác.`;

    case 'emotional': 
      return `
      - PHONG CÁCH: Cảm xúc, sâu lắng, chiêm nghiệm, đàn ông từng trải.
      - NGÔI XƯNG: "Mình" (Tự sự), "Tôi" (Chiêm nghiệm), hoặc xưng tên.
      - ĐẶC ĐIỂM: Tập trung miêu tả nội tâm, dùng từ ngữ gợi hình. Chạm vào "nỗi đau" (pain point) hoặc khát vọng của đàn ông (sự nghiệp, gia đình, bản lĩnh).`;

    case 'edgy': 
      return `
      - PHONG CÁCH: Xéo xắt, châm biếm, thẳng thắn (brutal honesty), cá tính mạnh.
      - NGÔI XƯNG: "Tui - Mấy người", "Ông - Tui", "Tôi" (thái độ). KHÔNG DÙNG "Bà".
      - ĐẶC ĐIỂM: Dám nói những sự thật mất lòng, "bóc phốt", quan điểm đi ngược số đông. Câu văn sắc lẹm, gắt, không vòng vo.`;

    case 'concise': 
      return `
      - PHONG CÁCH: Tối giản, súc tích, thực dụng, đi thẳng vào vấn đề (No Bullshit).
      - NGÔI XƯNG: "Tôi - Bạn" hoặc hạn chế dùng ngôi xưng, tập trung vào thông tin.
      - ĐẶC ĐIỂM: Gạch đầu dòng, câu ngắn, bỏ hết từ thừa/từ đệm. Tập trung tuyệt đối vào giá trị/kiến thức.`;

    default: 
      return `
      - PHONG CÁCH: Tự nhiên, nam tính, thu hút người Việt.
      - NGÔI XƯNG: "Anh em - Mình" hoặc "Bạn - Mình".
      - ĐẶC ĐIỂM: Cân bằng giữa thông tin và giải trí.`;
  }
};

const getFormulaInstruction = (formula?: ScriptFormula): string => {
  switch (formula) {
    case 'pas': return "BẮT BUỘC DÙNG CÔNG THỨC PAS: Problem (Nêu vấn đề/Nỗi đau) -> Agitation (Xoáy sâu nỗi đau/Hậu quả) -> Solution (Giải pháp/Sản phẩm của bạn).";
    case 'aida': return "BẮT BUỘC DÙNG CÔNG THỨC AIDA: Attention (Gây chú ý ngay lập tức) -> Interest (Tạo sự thích thú) -> Desire (Khơi gợi khao khát) -> Action (Kêu gọi hành động).";
    case 'storytelling': return "BẮT BUỘC DÙNG CẤU TRÚC STORYTELLING: Giới thiệu nhân vật/bối cảnh -> Biến cố/Xung đột -> Hành trình giải quyết -> Kết quả & Bài học.";
    case 'educational': return "BẮT BUỘC DÙNG CẤU TRÚC EDU: Hook (Sự thật/Lầm tưởng) -> Giải thích (Why) -> Hướng dẫn (How) -> Kết quả (What).";
    case 'before_after': return "BẮT BUỘC DÙNG CẤU TRÚC BEFORE-AFTER: Tình trạng tồi tệ trước đó -> Khoảnh khắc thay đổi (Bridge) -> Kết quả tuyệt vời hiện tại.";
    default: return "Bạn hãy TỰ PHÂN TÍCH nội dung và chọn công thức viral phù hợp nhất (Ví dụ: Biến hình, Review, Drama...).";
  }
};

