            <th class="p-3 border border-emerald-800 w-1/2">Lời thoại (Script)</th>
            <th class="p-3 border border-emerald-800 w-1/3">Mô tả Visual / Hành động / Góc máy</th>
          </tr>
        </thead>
        <tbody class="text-sm text-slate-200">
          <tr class="border-b border-emerald-900/30">
            <td class="p-3 border border-emerald-800 font-bold text-emerald-300">0-3s (HOOK)</td>
            <td class="p-3 border border-emerald-800">...</td>
            <td class="p-3 border border-emerald-800 italic text-slate-400">...</td>
          </tr>
          <!-- Các phần tiếp theo -->
        </tbody>
      </table>

      Sau bảng, hãy thêm một vài dòng "Đạo diễn ghi chú" về nhạc nền (BGM) nên dùng hoặc tone giọng (Voiceover) phù hợp.
      `;

    default:
      return "Phân tích nội dung này.";
  }
};

const cleanResponse = (text: string): string => {
  // Remove markdown code fences if present (e.g. ```html ... ```)
  let cleaned = text.trim();
  if (cleaned.startsWith("```html")) {
    cleaned = cleaned.substring(7);
  } else if (cleaned.startsWith("```")) {
    cleaned = cleaned.substring(3);
  }

  if (cleaned.endsWith("```")) {
    cleaned = cleaned.substring(0, cleaned.length - 3);
  }
  return cleaned;
};

// Fix: Updated to comply with @google/genai guidelines (initializing with process.env.API_KEY, using gemini-3-flash-preview, and correct request structure)
export const analyzeContent = async (
  _apiKey: string, // Signature kept for compatibility, but sdk requirement is process.env.API_KEY
  mode: AnalysisMode,
  base64Data: string, 
  mimeType: string,   
  userPrompt?: string,
  contextData?: string,
  url?: string, 
  tone?: ContentTone,
  additionalInstructions?: string,
  formula?: ScriptFormula
): Promise<string> => {

  // Use named parameter and direct process.env.API_KEY as per guidelines
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Select appropriate model based on task
  const modelId = 'gemini-3-flash-preview'; 

  let parts: any[] = [];

  if (mode === AnalysisMode.CONTENT_REMAKE && contextData) {
     parts.push({ text: `Dữ liệu gốc đã trích xuất:\n${contextData}` });
  } 
  else if (base64Data && mimeType) {
    parts.push({
      inlineData: {
        data: base64Data,
        mimeType: mimeType
      }
    });
  }

  const systemInstruction = getSystemInstruction(mode);
  let promptText = getPrompt(mode, userPrompt, url, tone, additionalInstructions, formula);

  if (url) {
    promptText += `\n\nLINK CẦN XỬ LÝ: ${url}`;
  }

  const config: any = {
    systemInstruction: systemInstruction,
    temperature: 0.8,
  };

  if (mode === AnalysisMode.CONTENT_AUDIT || url) {
    config.tools = [{ googleSearch: {} }];
  }

  try {
    const response = await ai.models.generateContent({
      model: modelId,
      contents: { parts: [...parts, { text: promptText }] }, // Correct parts structure
      config: config
    });

    const rawText = response.text || "Không có phản hồi từ AI.";
    return cleanResponse(rawText);
  } catch (error: any) {
    console.error("Gemini API Error:", error);
    throw new Error(error.message || "Đã xảy ra lỗi khi kết nối với Gemini AI.");
  }
};

// Fix: Updated generateRemakeThumbnail to follow sdk initialization and configuration rules
export const generateRemakeThumbnail = async (
  _apiKey: string, // Signature kept for compatibility
  competitorThumbBase64: string,
  userAssetBase64: string,
  userAssetMimeType: string,
  titleText: string,
  aspectRatio: string = "16:9"
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const modelId = 'gemini-3-pro-image-preview';

  const parts = [
    {
      inlineData: {
        data: competitorThumbBase64,
        mimeType: 'image/jpeg' 
      }
    },
    {
      inlineData: {
        data: userAssetBase64,
        mimeType: userAssetMimeType
      }
    },
    {
      text: `
      Create a YouTube thumbnail image.

      Reference Image 1: Competitor's thumbnail. Analyze its composition, color palette, high saturation style, and emotional hook.
      Reference Image 2: The user's asset (person/object).

      TASK: Generate a NEW thumbnail that uses the successful composition/style of Reference 1, but REPLACES the main subject with the subject from Reference 2.

      Requirements:
      - The subject from Reference 2 should be seamlessly integrated.
      - Background should be exciting, similar to Reference 1 but not identical (avoid copyright).
      - Include the text "${titleText}" in big, bold, readable 3D typography if possible, or leave space for it.
      - Style: High Quality, 4K, YouTube Clickbait style, Vibrant Colors, Expressive.
      - Aspect Ratio: ${aspectRatio}.
      `
    }
  ];

  try {
    const response = await ai.models.generateContent({
      model: modelId,
      contents: { parts },
      config: {
        imageConfig: {
          aspectRatio: aspectRatio as any,
          imageSize: "1K"
        }
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }

    throw new Error("Không tạo được hình ảnh. Vui lòng thử lại.");
  } catch (error: any) {
    console.error("Gemini Image Gen Error:", error);
    throw new Error(error.message || "Lỗi khi tạo hình ảnh thumbnail.");
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { Sparkles, AlertCircle, Copy, Check, Video, ExternalLink, Loader2, Link as LinkIcon, Download, Wand2, PenTool, RefreshCw, Globe, ShieldAlert, Monitor, Camera, X, MessageSquareQuote, FilePenLine, Trash2, Mic, Sigma } from 'lucide-react';
import { AnalysisMode, LoadingState, FileData, ContentTone, TONE_LABELS, ScriptFormula, FORMULA_LABELS } from './types';
import { analyzeContent, fileToGenerativePart, generateRemakeThumbnail } from './services/geminiService';
import { Button, FeatureCard, FileDropzone } from './components/UiComponents';

const App = () => {
  const [fileData, setFileData] = useState<FileData | null>(null);
  const [selectedMode, setSelectedMode] = useState<AnalysisMode>(AnalysisMode.SCRIPT_EXTRACT);
  const [result, setResult] = useState<string>('');
  const [loading, setLoading] = useState<LoadingState>({ isLoading: false, message: '' });
  const [error, setError] = useState<string>('');
  const [copied, setCopied] = useState(false);
  const [urlInput, setUrlInput] = useState('');
  const [customUserPrompt, setCustomUserPrompt] = useState('');
  const [userInstructions, setUserInstructions] = useState('');
  const [selectedTone, setSelectedTone] = useState<ContentTone>('funny');
  const [selectedFormula, setSelectedFormula] = useState<ScriptFormula>('auto');

  const [userAssetData, setUserAssetData] = useState<FileData | null>(null);
  const [thumbnailText, setThumbnailText] = useState('');
  const [generatedImageUrl, setGeneratedImageUrl] = useState<string>('');
  const [aspectRatio, setAspectRatio] = useState<'16:9' | '9:16'>('16:9');

  const [screenStream, setScreenStream] = useState<MediaStream | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);

  const resultRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    return () => {
      if (screenStream) {
        screenStream.getTracks().forEach(track => track.stop());
      }
    };
  }, [screenStream]);

  const handleFileSelect = async (file: File) => {
    stopScreenShare();
    setError('');
    setResult('');
    setGeneratedImageUrl('');
    setUrlInput('');
    setUserAssetData(null);
    setAspectRatio('16:9');

    if (file.size > 500 * 1024 * 1024) {
      setError("File quá lớn! Vui lòng chọn file dưới 500MB.");
      return;
    }

    const type = file.type.startsWith('video') ? 'video' : 
                 file.type.startsWith('audio') ? 'audio' : 'image';

    if (type === 'image') {
      if (selectedMode !== AnalysisMode.CONTENT_AUDIT && selectedMode !== AnalysisMode.SCRIPT_GENERATION) {
          setSelectedMode(AnalysisMode.THUMBNAIL_AUDIT);
      }
    } else if (type === 'audio') {
      setSelectedMode(AnalysisMode.CONTENT_AUDIT);
    } else if (selectedMode === AnalysisMode.THUMBNAIL_AUDIT) {
      setSelectedMode(AnalysisMode.SCRIPT_EXTRACT);
    }

    try {
      const { inlineData } = await fileToGenerativePart(file);
      setFileData({
        file,
        previewUrl: URL.createObjectURL(file),
        type,
        base64: inlineData.data,
        mimeType: inlineData.mimeType
      });
    } catch (e) {
      setError("Lỗi khi xử lý file. Vui lòng thử lại.");
    }
  };

  const handleUserAssetSelect = async (file: File) => {
    if (!file.type.startsWith('image')) {
       setError("Vui lòng chỉ tải lên file ảnh (JPG, PNG).");
       return;
    }

    try {
      const { inlineData } = await fileToGenerativePart(file);
      setUserAssetData({
        file,
        previewUrl: URL.createObjectURL(file),
        type: 'image',
        base64: inlineData.data,
        mimeType: inlineData.mimeType
      });
    } catch (e) {
      setError("Lỗi xử lý file element của bạn.");
    }
  };

  const handleClearData = () => {
    setFileData(null);
    setResult('');
    setError('');
    setUrlInput('');
    setGeneratedImageUrl('');
    stopScreenShare();
  };

  const startScreenShare = async () => {
    setError('');
    setFileData(null);
    setUrlInput('');
    setResult('');

    try {
      const stream = await navigator.mediaDevices.getDisplayMedia({ 
        video: { cursor: "always" } as any, 
        audio: false 
      });

      setScreenStream(stream);
      stream.getVideoTracks()[0].onended = () => {
        setScreenStream(null);
      };

      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
    } catch (err: any) {
      console.error("Screen share error:", err);
      if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError' || (err.message && err.message.includes('Permission denied'))) {
         console.log("User cancelled screen share");
      } else {
         setError("Không thể chia sẻ màn hình: " + (err.message || "Vui lòng kiểm tra quyền truy cập."));
      }
    }
  };

  const stopScreenShare = () => {
    if (screenStream) {
      screenStream.getTracks().forEach(track => track.stop());
      setScreenStream(null);
    }
  };

  const captureScreenAndAnalyze = async () => {
    if (!videoRef.current || !screenStream) return;
    setLoading({ isLoading: true, message: 'Đang chụp màn hình...' });

    try {
      const canvas = document.createElement('canvas');
      const video = videoRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (!ctx) throw new Error("Could not get canvas context");
      ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

      canvas.toBlob(async (blob) => {
        if (!blob) {
           setError("Lỗi khi chụp màn hình.");
           setLoading({ isLoading: false, message: '' });
           return;
        }
        stopScreenShare();
        const { inlineData } = await fileToGenerativePart(blob);
        setFileData({
          file: null,
          previewUrl: URL.createObjectURL(blob),
          type: 'image',
          base64: inlineData.data,
          mimeType: 'image/jpeg'
        });
        setLoading({ isLoading: true, message: 'AI đang phân tích nội dung...' });
        try {
           const responseText = await analyzeContent(
            '', // API Key is managed internally by the service via process.env
            selectedMode,
            inlineData.data,
            'image/jpeg',
            customUserPrompt,
            undefined,
            undefined,
            selectedTone,
            userInstructions
          );
          setResult(responseText);
          setTimeout(() => {
            resultRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
          }, 100);
        } catch (apiErr: any) {
          setError(apiErr.message);
        } finally {
          setLoading({ isLoading: false, message: '' });
        }
      }, 'image/jpeg', 0.95);
    } catch (err: any) {
      setError("Lỗi khi xử lý ảnh chụp: " + err.message);
      setLoading({ isLoading: false, message: '' });
    }
  };

  const downloadCurrentFile = async () => {
    if (!fileData || !fileData.previewUrl) return;

    try {
      if (fileData.file) {
        const link = document.createElement('a');
        link.href = fileData.previewUrl;
        link.download = fileData.file.name;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        return;
      }

      const response = await fetch(fileData.previewUrl);
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;

      const timestamp = new Date().getTime();
      const extension = fileData.mimeType.split('/')[1]?.split(';')[0] || 'bin';
      link.download = `content-creator-export-${timestamp}.${extension}`;

      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(url);
    } catch (err) {
      console.error("Download error:", err);
      setError("Không thể tải xuống file này trực tiếp. Hãy thử 'Chuột phải -> Lưu thành' trên video/ảnh.");
    }
  };

  const handleUrlFetch = async () => {
    if (!urlInput.trim()) return;

    if ((selectedMode as AnalysisMode) === AnalysisMode.CONTENT_AUDIT) {
        setFileData({
             file: null,
             previewUrl: '',
             type: 'url',
             base64: '',
             mimeType: '',
             url: urlInput
        });
        setError('');
        setResult('');
        return;
    }

    setLoading({ isLoading: true, message: 'Đang kiểm tra liên kết...' });
    setError('');
    setResult('');
    setFileData(null);
    setGeneratedImageUrl('');
    setUserAssetData(null);
    stopScreenShare();

    try {
      let blob: Blob;
      try {
        const response = await fetch(urlInput);
        if (!response.ok) throw new Error('Direct fetch failed');
        blob = await response.blob();
      } catch (directError) {
        const isSocialLink = /(youtube\.com|youtu\.be|tiktok\.com|facebook\.com|instagram\.com|x\.com|twitter\.com|threads\.net)/i.test(urlInput);
        if (isSocialLink) {
           setFileData({
              file: null,
              previewUrl: '',
              type: 'url',
              base64: '',
              mimeType: '',
              url: urlInput
           });
           setError("Link MXH được nhận diện. Đối với YouTube/TikTok, trình duyệt không thể tải trực tiếp file gốc do chính sách CORS. Bạn hãy dùng các tool tải video chuyên dụng, sau đó tải file lên đây để phân tích.");
           setLoading({ isLoading: false, message: '' });
           return;
        }

        try {
          const proxyUrl = `https://corsproxy.io/?${encodeURIComponent(urlInput)}`;
          const proxyResponse = await fetch(proxyUrl);
          if (!proxyResponse.ok) throw new Error('Proxy fetch failed');
          blob = await proxyResponse.blob();
        } catch (proxyError) {
           setFileData({
              file: null,
              previewUrl: '',
              type: 'url',
              base64: '',
              mimeType: '',
              url: urlInput
           });
           setError("Không tải được file trực tiếp. Đã chuyển sang chế độ đọc Link.");
           setLoading({ isLoading: false, message: '' });
           return;
        }
      }

      let mimeType = blob.type;
      if (!mimeType || mimeType === 'application/octet-stream') {
         const ext = urlInput.split('.').pop()?.toLowerCase();
         if (['jpg', 'jpeg'].includes(ext || '')) mimeType = 'image/jpeg';
         else if (['png'].includes(ext || '')) mimeType = 'image/png';
         else if (['mov'].includes(ext || '')) mimeType = 'video/quicktime';
         else if (['mp3', 'wav', 'ogg'].includes(ext || '')) mimeType = 'audio/mpeg';
         else mimeType = 'video/mp4';
         blob = blob.slice(0, blob.size, mimeType);
      }

      if (mimeType.includes('text/html')) {
          setFileData({
              file: null,
              previewUrl: '',
              type: 'url',
              base64: '',
              mimeType: '',
              url: urlInput
           });
           setError("Link này là trang web. Đã chuyển sang chế độ đọc Link.");
           setLoading({ isLoading: false, message: '' });
           return;
      }

      if (blob.size > 500 * 1024 * 1024) {
        throw new Error("File từ link quá lớn (>500MB). Vui lòng dùng file nhỏ hơn.");
      }

      const type = mimeType.startsWith('image') ? 'image' : 
                   mimeType.startsWith('audio') ? 'audio' : 'video';

      if (type === 'image') {
        if (selectedMode !== AnalysisMode.CONTENT_AUDIT && selectedMode !== AnalysisMode.SCRIPT_GENERATION) {
           setSelectedMode(AnalysisMode.THUMBNAIL_AUDIT);
        }
      } else if (type === 'audio') {
         setSelectedMode(AnalysisMode.CONTENT_AUDIT);
      } else if (selectedMode === AnalysisMode.THUMBNAIL_AUDIT) {
        setSelectedMode(AnalysisMode.SCRIPT_EXTRACT);
      }

      const { inlineData } = await fileToGenerativePart(blob);
      setFileData({
        file: null,
        previewUrl: URL.createObjectURL(blob),
        type,
        base64: inlineData.data,
        mimeType: mimeType
      });

    } catch (err: any) {
      console.error(err);
      setError("Lỗi tải link: " + (err.message || "Vui lòng kiểm tra lại đường dẫn."));
    } finally {
      setLoading({ isLoading: false, message: '' });
    }
  };

  const handleAnalyze = async () => {
    if (!fileData && selectedMode !== AnalysisMode.CONTENT_AUDIT && selectedMode !== AnalysisMode.SCRIPT_GENERATION) return;

    const isTextMode = selectedMode === AnalysisMode.CONTENT_AUDIT || selectedMode === AnalysisMode.SCRIPT_GENERATION;
    if (isTextMode && !fileData && !customUserPrompt.trim()) {
        setError("Vui lòng nhập ý tưởng/nội dung văn bản, hoặc dán link/ảnh/audio.");
        return;
    }

    setLoading({ isLoading: true, message: 'AI đang phân tích nội dung...' });
    setError('');
    setResult('');
    setGeneratedImageUrl('');

    try {
      const responseText = await analyzeContent(
        '', // Internal process.env.API_KEY is used
        selectedMode,
        fileData?.base64 || '',
        fileData?.mimeType || '',
        isTextMode ? customUserPrompt : undefined,
        undefined,
        fileData?.url,
        selectedTone,
        userInstructions,
        selectedFormula
      );
      setResult(responseText);

      setTimeout(() => {
        resultRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }, 100);

    } catch (err: any) {
      setError(err.message || "Đã có lỗi xảy ra trong quá trình phân tích.");
    } finally {
      setLoading({ isLoading: false, message: '' });
    }
  };

  const handleRemakeThumbnail = async () => {
    if (!fileData || !userAssetData) return;

    // Requirement: User must select their own API key via AI Studio dialog for Imagen/Pro models
    if (window.aistudio) {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) {
        await window.aistudio.openSelectKey();
      }
    }

    setLoading({ isLoading: true, message: 'Nano Banana Pro đang vẽ lại thumbnail (sẽ mất khoảng 15-20s)...' });
    setError('');

    try {
      const generatedImageBase64 = await generateRemakeThumbnail(
        '', // SDK uses process.env.API_KEY
        fileData.base64,
        userAssetData.base64,
        userAssetData.mimeType,
        thumbnailText || "Hot Video",
        aspectRatio
      );
      setGeneratedImageUrl(generatedImageBase64);
      setTimeout(() => {
        window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
      }, 100);
    } catch (err: any) {
      setError(err.message || "Lỗi khi tạo thumbnail remake.");
    } finally {
      setLoading({ isLoading: false, message: '' });
    }
  };

  const copyToClipboard = () => {
    const tempDiv = document.createElement('div');
    tempDiv.innerHTML = result;
    const textToCopy = tempDiv.textContent || tempDiv.innerText || "";
    navigator.clipboard.writeText(textToCopy);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const showToneSelector = [
    AnalysisMode.REMAKE_SCRIPT, 
    AnalysisMode.CONTENT_AUDIT, 
    AnalysisMode.SCRIPT_GENERATION, 
    AnalysisMode.CONTENT_REMAKE
  ].includes(selectedMode);

  return (
    <div className="min-h-screen bg-[#0f172a] text-slate-200 p-4 md:p-8">
      <div className="max-w-5xl mx-auto space-y-8">

        <header className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4 border-b border-slate-800 pb-6">
          <div className="flex items-center gap-3">
            <div className="p-3 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-xl shadow-lg shadow-indigo-500/20">
              <Sparkles className="w-6 h-6 text-white" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-white tracking-tight">ContentCreator AI</h1>
              <p className="text-slate-400 text-sm">Phân tích đối thủ & Remake nội dung siêu tốc</p>
            </div>
          </div>
        </header>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          <div className="lg:col-span-5 space-y-6">
            <div className="bg-slate-800/50 p-4 rounded-xl border border-slate-700">
               <label className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-2 block">
                 Bước 1: Nhập nguồn (Link/File)
               </label>
               <div className="flex gap-2 mb-3">
                 <div className="relative flex-1">
                    <LinkIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                    <input 
                      type="text" 
                      value={urlInput}
                      onChange={(e) => setUrlInput(e.target.value)}
                      placeholder="Paste link video/ảnh/bài viết Facebook, Web..." 
                      className="w-full bg-slate-900 border border-slate-700 rounded-lg py-2 pl-10 pr-4 text-sm text-slate-300 focus:outline-none focus:border-indigo-500 transition-colors"
                      disabled={!!screenStream}
                    />
                 </div>
                 <Button 
                   variant="secondary" 
                   className="shrink-0" 
                   onClick={handleUrlFetch}
                   disabled={loading.isLoading || !urlInput.trim() || !!screenStream}
                   title="Fetch để xem trước & phân tích"
                 >
                   {loading.isLoading && urlInput ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Fetch'}
                 </Button>
               </div>

               <div className="mt-4 space-y-3">
                  {!screenStream && (
                    <FileDropzone 
                      onFileSelect={handleFileSelect} 
                      currentFile={fileData?.file || null} 
                      label="Hoặc Kéo thả Video, Audio, Ảnh"
                    />
                  )}

                  {selectedMode === AnalysisMode.CONTENT_AUDIT && (
                    <div className="relative">
                      {!screenStream ? (
                        <button 
                          onClick={startScreenShare}
                          className="w-full py-3 px-4 rounded-xl border border-dashed border-indigo-500/50 bg-indigo-500/10 hover:bg-indigo-500/20 text-indigo-300 flex items-center justify-center gap-2 transition-all group"
                        >
                          <Monitor className="w-5 h-5 group-hover:scale-110 transition-transform" />
                          <span className="font-medium">Live Screen Capture (Chụp & Remake)</span>
                        </button>
                      ) : (
                        <div className="bg-slate-900 rounded-xl overflow-hidden border border-indigo-500 shadow-xl relative animate-in zoom-in-95">
                          <div className="bg-indigo-600 px-3 py-1.5 flex items-center justify-between text-white text-xs font-medium">
                            <span className="flex items-center gap-1.5"><Monitor className="w-3.5 h-3.5" /> Đang xem màn hình của bạn</span>
                            <button onClick={stopScreenShare} className="hover:bg-indigo-700 rounded p-1"><X className="w-3.5 h-3.5" /></button>
                          </div>
                          <div className="relative aspect-video bg-black">
                             <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-contain" />
                          </div>
                          <div className="p-3 bg-slate-800 border-t border-slate-700 flex justify-center">
                            <Button onClick={captureScreenAndAnalyze} className="w-full">
                              <Camera className="w-4 h-4 mr-2" />
                              Chụp & Remake Ngay
                            </Button>
                          </div>
                        </div>
                      )}
                    </div>
                  )}
               </div>
            </div>

            <div className="space-y-3">
              <label className="text-xs font-semibold text-slate-400 uppercase tracking-wider block">
                Bước 2: Chọn Tính Năng
              </label>
              <div className="grid grid-cols-2 gap-3">
                <FeatureCard 
                  mode={AnalysisMode.SCRIPT_EXTRACT} 
                  active={selectedMode === AnalysisMode.SCRIPT_EXTRACT} 
                  onClick={() => { setSelectedMode(AnalysisMode.SCRIPT_EXTRACT); stopScreenShare(); }}
                  disabled={fileData?.type === 'image' || !!screenStream}
                />
                <FeatureCard 
                  mode={AnalysisMode.DEEP_ANALYSIS} 
                  active={selectedMode === AnalysisMode.DEEP_ANALYSIS} 
                  onClick={() => { setSelectedMode(AnalysisMode.DEEP_ANALYSIS); stopScreenShare(); }}
                  disabled={fileData?.type === 'image' || !!screenStream}
                />
                <FeatureCard 
                  mode={AnalysisMode.THUMBNAIL_AUDIT} 
                  active={selectedMode === AnalysisMode.THUMBNAIL_AUDIT} 
                  onClick={() => { setSelectedMode(AnalysisMode.THUMBNAIL_AUDIT); stopScreenShare(); }}
                  disabled={fileData?.type === 'video' || fileData?.type === 'audio' || !!screenStream}
                />
                <FeatureCard 
                  mode={AnalysisMode.CONTENT_AUDIT} 
                  active={selectedMode === AnalysisMode.CONTENT_AUDIT} 
                  onClick={() => setSelectedMode(AnalysisMode.CONTENT_AUDIT)}
                  disabled={fileData?.type === 'video'} 
                />
                <FeatureCard 
                  mode={AnalysisMode.REMAKE_SCRIPT} 
                  active={selectedMode === AnalysisMode.REMAKE_SCRIPT} 
                  onClick={() => { setSelectedMode(AnalysisMode.REMAKE_SCRIPT); stopScreenShare(); }}
                  disabled={fileData?.type === 'image' || fileData?.type === 'audio' || !!screenStream}
                />
                <FeatureCard 
                  mode={AnalysisMode.SCRIPT_GENERATION} 
                  active={selectedMode === AnalysisMode.SCRIPT_GENERATION} 
                  onClick={() => { setSelectedMode(AnalysisMode.SCRIPT_GENERATION); stopScreenShare(); }}
                  disabled={false}
                />
              </div>
            </div>

            {selectedMode === AnalysisMode.SCRIPT_GENERATION && (
              <div className="space-y-2 animate-in fade-in slide-in-from-top-2">
                 <label className="text-xs font-semibold text-orange-400 uppercase tracking-wider block flex items-center gap-1">
                    <Sigma className="w-3 h-3" /> Công thức Kịch bản (Viral Structure)
                  </label>
                  <select 
                    value={selectedFormula}
                    onChange={(e) => setSelectedFormula(e.target.value as ScriptFormula)}
                    className="w-full bg-slate-800 border border-slate-700 text-slate-200 text-sm rounded-lg p-3 focus:border-orange-500 outline-none"
                  >
                    {(Object.keys(FORMULA_LABELS) as ScriptFormula[]).map((f) => (
                      <option key={f} value={f}>{FORMULA_LABELS[f]}</option>
                    ))}
                  </select>
              </div>
            )}

            {showToneSelector && (
              <div className="space-y-4 animate-in fade-in slide-in-from-top-2">
                <div className="space-y-2">
                  <label className="text-xs font-semibold text-pink-400 uppercase tracking-wider block flex items-center gap-1">
                    <MessageSquareQuote className="w-3 h-3" /> Chọn Giọng Văn (Tone)
                  </label>
                  <div className="grid grid-cols-2 gap-2">
                    {(Object.keys(TONE_LABELS) as ContentTone[]).map((tone) => (
                      <button
                        key={tone}
                        onClick={() => setSelectedTone(tone)}
                        className={`
                          text-xs py-2 px-3 rounded-lg border transition-all text-left truncate
                          ${selectedTone === tone 
                            ? 'bg-pink-500/20 border-pink-500 text-pink-200 shadow-[0_0_10px_rgba(236,72,153,0.3)]' 
                            : 'bg-slate-800 border-slate-700 text-slate-400 hover:bg-slate-700 hover:text-slate-200'}
                        `}
                      >
                        {TONE_LABELS[tone]}
                      </button>
                    ))}
                  </div>
                </div>

                <div className="space-y-2">
                   <label className="text-xs font-semibold text-emerald-400 uppercase tracking-wider block flex items-center gap-1">
                    <FilePenLine className="w-3 h-3" /> Yêu cầu tùy chỉnh (Custom Prompt)
                  </label>
                  <textarea 
                    className="w-full bg-slate-800 border border-slate-700 rounded-lg p-3 text-sm text-slate-200 focus:border-emerald-500 outline-none h-20 resize-none custom-scrollbar placeholder:text-slate-500"
                    placeholder="VD: Nhấn mạnh vào giá rẻ, thêm 3 hashtag, viết ngắn gọn dưới 300 từ..."
                    value={userInstructions}
                    onChange={(e) => setUserInstructions(e.target.value)}
                  />
                </div>
              </div>
            )}

            {(selectedMode === AnalysisMode.CONTENT_AUDIT || selectedMode === AnalysisMode.SCRIPT_GENERATION) && (
              <div className="space-y-2 animate-in fade-in slide-in-from-top-2">
                <label className="text-xs font-semibold text-indigo-400 uppercase tracking-wider block flex items-center gap-1">
                  <PenTool className="w-3 h-3" /> 
                  {selectedMode === AnalysisMode.SCRIPT_GENERATION ? 'Ý tưởng / Bản nháp (Draft) của bạn' : 'Nội dung gốc (Text) hoặc Yêu cầu'}
                </label>
                <textarea
                  className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-sm text-slate-200 focus:border-indigo-500 outline-none h-40 resize-none custom-scrollbar"
                  placeholder={selectedMode === AnalysisMode.SCRIPT_GENERATION ? "Ví dụ: Mình muốn làm video về sai lầm khi mới nuôi mèo..." : "Paste đoạn văn bản gốc bạn muốn Remake vào đây..."}
                  value={customUserPrompt}
                  onChange={(e) => setCustomUserPrompt(e.target.value)}
                />
              </div>
            )}

            {!screenStream && (
              <Button 
                onClick={handleAnalyze} 
                disabled={(!fileData && !customUserPrompt && (selectedMode === AnalysisMode.CONTENT_AUDIT || selectedMode === AnalysisMode.SCRIPT_GENERATION)) || (!fileData && selectedMode !== AnalysisMode.CONTENT_AUDIT && selectedMode !== AnalysisMode.SCRIPT_GENERATION) || loading.isLoading} 
                className="w-full py-4 text-lg shadow-xl shadow-indigo-900/20"
              >
                {loading.isLoading && !urlInput && !userAssetData ? (
                  <>
                    <Loader2 className="w-5 h-5 animate-spin" />
                    {loading.message}
                  </>
                ) : (
                  <>
                    <Sparkles className="w-5 h-5" />
                    {selectedMode === AnalysisMode.CONTENT_AUDIT ? "Remake Bài Viết Ngay" : 
                     selectedMode === AnalysisMode.SCRIPT_GENERATION ? "Tạo Kịch Bản Viral" : 
                     "Bắt Đầu Phân Tích AI"}
                  </>
                )}
              </Button>
            )}

             {error && (
              <div className="p-4 bg-amber-500/10 border border-amber-500/20 rounded-xl text-amber-200 text-sm flex items-start gap-3 animate-in fade-in slide-in-from-top-2">
                <AlertCircle className="w-5 h-5 shrink-0 mt-0.5" />
                <div>{error}</div>
              </div>
            )}
          </div>

          <div className="lg:col-span-7 space-y-6">

            {fileData && (
              <div className="bg-slate-900 rounded-xl overflow-hidden border border-slate-800 shadow-2xl relative group">
                <div className="absolute top-2 left-2 z-10 bg-black/60 backdrop-blur-md px-3 py-1 rounded-full text-xs font-medium text-white border border-white/10">
                  {fileData.file ? 'Local File' : fileData.type === 'url' ? 'Web Link' : 'URL Source'}
                </div>

                <div className="absolute top-2 right-2 z-20 flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                  {fileData.previewUrl && (
                    <button 
                      onClick={downloadCurrentFile}
                      className="bg-indigo-500 hover:bg-indigo-600 text-white p-2 rounded-full transition-colors"
                      title="Tải video/ảnh về máy"
                    >
                      <Download className="w-4 h-4" />
                    </button>
                  )}
                  <button 
                    onClick={handleClearData}
                    className="bg-red-500/80 hover:bg-red-600 text-white p-2 rounded-full transition-colors"
                    title="Xóa / Chọn file khác"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>

                {fileData.type === 'video' ? (
                  <video 
                    src={fileData.previewUrl} 
                    controls 
                    className="w-full max-h-[300px] object-contain bg-black" 
                  />
                ) : fileData.type === 'audio' ? (
                  <div className="h-[150px] flex flex-col items-center justify-center bg-slate-800/50 text-indigo-300 gap-3 px-8">
                      <Mic className="w-12 h-12 text-pink-400" />
                      <audio src={fileData.previewUrl} controls className="w-full max-w-md" />
                      <p className="text-xs text-slate-500">{fileData.file?.name || 'Audio File'}</p>
                   </div>
                ) : fileData.type === 'url' ? (
                   <div className="h-[200px] flex flex-col items-center justify-center bg-slate-800/50 text-indigo-300 gap-3">
                      <Globe className="w-12 h-12 opacity-50" />
                      <div className="text-center px-4">
                        <p className="font-semibold text-white">Phân tích qua Đường Dẫn (Link)</p>
                        <p className="text-sm text-slate-400 truncate max-w-md mt-1">{fileData.url}</p>
                        <p className="text-xs text-slate-500 mt-2">Sử dụng Google Search Grounding để đọc nội dung</p>
                      </div>
                   </div>
                ) : (
                  <img 
                    src={fileData.previewUrl} 
                    alt="Preview" 
                    className="w-full max-h-[300px] object-contain bg-black" 
                  />
                )}
              </div>
            )}

            <div ref={resultRef} className="bg-slate-800/50 rounded-2xl border border-slate-700 min-h-[400px] flex flex-col shadow-inner">
              <div className="p-4 border-b border-slate-700 flex items-center justify-between bg-slate-800/80 rounded-t-2xl">
                <h3 className="font-semibold text-white flex items-center gap-2">
                  <Sparkles className="w-4 h-4 text-indigo-400" />
                  Kết Quả Phân Tích
                </h3>
                {result && (
                  <button 
                    onClick={copyToClipboard}
                    className="text-xs flex items-center gap-1.5 text-slate-400 hover:text-white transition-colors bg-slate-700 hover:bg-slate-600 px-3 py-1.5 rounded-lg"
                  >
                    {copied ? <Check className="w-3.5 h-3.5 text-green-400" /> : <Copy className="w-3.5 h-3.5" />}
                    {copied ? "Đã copy" : "Copy nội dung"}
                  </button>
                )}
              </div>

              <div className="p-6 flex-1 overflow-y-auto max-h-[600px] custom-scrollbar">
                {result ? (
                  <div className="space-y-6">
                     <div className="prose prose-invert prose-p:text-slate-300 prose-headings:text-white prose-strong:text-indigo-300 prose-ul:text-slate-300 max-w-none">
                        <div 
                          className="font-sans leading-relaxed text-sm md:text-base space-y-4"
                          dangerouslySetInnerHTML={{ __html: result }}
                        />
                     </div>

                     {selectedMode === AnalysisMode.THUMBNAIL_AUDIT && (
                       <div className="mt-8 border-t border-slate-700 pt-8 animate-in fade-in">
                          <div className="flex items-center gap-2 mb-4 text-indigo-300">
                             <Wand2 className="w-5 h-5" />
                             <h3 className="text-lg font-bold">Remake Thumbnail với Nano Banana Pro</h3>
                          </div>

                          <div className="bg-slate-900/50 rounded-xl p-5 border border-indigo-500/30 space-y-4">
                             <div className="space-y-2">
                                <label className="text-xs uppercase text-slate-500 font-semibold">1. Upload ảnh của bạn (Khuôn mặt / Sản phẩm)</label>
                                <FileDropzone 
                                  variant="mini" 
                                  onFileSelect={handleUserAssetSelect} 
                                  currentFile={userAssetData?.file || null}
                                  label="Thả ảnh khuôn mặt hoặc sản phẩm của bạn vào đây"
                                />
                             </div>

                             <div className="space-y-2">
                                <label className="text-xs uppercase text-slate-500 font-semibold">2. Tiêu đề trên Thumbnail mới</label>
                                <input 
                                  type="text" 
                                  className="w-full bg-slate-800 border border-slate-700 rounded-lg p-3 text-sm text-white focus:border-indigo-500 outline-none"
                                  placeholder="Ví dụ: BÍ MẬT TRIỆU VIEW..."
                                  value={thumbnailText}
                                  onChange={(e) => setThumbnailText(e.target.value)}
                                />
                             </div>

                             <div className="space-y-2">
                                <label className="text-xs uppercase text-slate-500 font-semibold">3. Tỉ lệ khung hình</label>
                                <div className="grid grid-cols-2 gap-3">
                                  <button
                                    onClick={() => setAspectRatio('16:9')}
                                    className={`flex items-center justify-center gap-2 py-3 rounded-lg border text-sm font-medium transition-all ${aspectRatio === '16:9' ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg shadow-indigo-500/20' : 'bg-slate-800 border-slate-700 text-slate-400 hover:bg-slate-700'}`}
                                  >
                                    <div className="w-6 h-3.5 border-2 border-current rounded-sm"></div>
                                    16:9 (YouTube)
                                  </button>
                                  <button
                                    onClick={() => setAspectRatio('9:16')}
                                    className={`flex items-center justify-center gap-2 py-3 rounded-lg border text-sm font-medium transition-all ${aspectRatio === '9:16' ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg shadow-indigo-500/20' : 'bg-slate-800 border-slate-700 text-slate-400 hover:bg-slate-700'}`}
                                  >
                                    <div className="w-3.5 h-6 border-2 border-current rounded-sm"></div>
                                    9:16 (Shorts)
                                  </button>
                                </div>
                             </div>

                             <Button 
                               onClick={handleRemakeThumbnail}
                               disabled={!userAssetData || loading.isLoading}
                               className="w-full mt-2"
                             >
                               {loading.isLoading && userAssetData ? (
                                 <><Loader2 className="animate-spin w-4 h-4"/> Đang vẽ (15s)...</>
                               ) : "Tạo Thumbnail Mới"}
                             </Button>
                          </div>
                       </div>
                     )}

                     {generatedImageUrl && (
                       <div className="mt-6 space-y-3 animate-in zoom-in-95 duration-500">
                          <h4 className="text-green-400 font-semibold flex items-center gap-2">
                            <Check className="w-4 h-4" /> Thumbnail Remake Hoàn Tất
                          </h4>
                          <div className={`rounded-xl overflow-hidden border-2 border-indigo-500/50 shadow-2xl relative group mx-auto ${aspectRatio === '9:16' ? 'max-w-[300px]' : 'w-full'}`}>
                             <img src={generatedImageUrl} alt="Generated Thumbnail" className="w-full h-auto" />
                             <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                                <a 
                                  href={generatedImageUrl} 
                                  download={`remake-thumbnail-${aspectRatio.replace(':','-')}.png`}
                                  className="bg-white text-black px-6 py-3 rounded-full font-bold flex items-center gap-2 hover:scale-105 transition-transform"
                                >
                                  <Download className="w-5 h-5" /> Tải Xuống
                                </a>
                             </div>
                          </div>
                          <p className="text-xs text-slate-500 italic text-center">
                            *Hình ảnh được tạo bởi AI Google Gemini 3 Pro Vision (Nano Banana 2).
                          </p>
                       </div>
                     )}
                  </div>
                ) : (
                  <div className="h-full flex flex-col items-center justify-center text-slate-500 opacity-60 min-h-[300px]">
                    <Sparkles className="w-12 h-12 mb-3 text-slate-600" />
                    <p>Kết quả phân tích sẽ hiển thị ở đây</p>
                  </div>
                )}
              </div>
            </div>

          </div>
        </div>

        <footer className="text-center text-slate-600 text-sm py-8 border-t border-slate-800/50">
          <p>© 2024 ContentCreator AI. Powered by Google Gemini 3 Flash & Nano Banana 2.</p>
        </footer>
      </div>
    </div>
  );
};

export default App;
